mapper.select:
select a.apt_id as appointmentId, a.apt_candidate_id as candidateId, a.apt_position_id as positionId, a.apt_interviewer_id as interviewerId, a.apt_slot_id as slotId, a.apt_status as status, date_format(a.apt_start_time, '%Y-%m-%d %H:%i') as startTime, date_format(a.apt_end_time, '%Y-%m-%d %H:%i') as endTime, a.apt_meeting_url as meetingUrl, a.apt_room_id as roomId, u.nick_name as candidateName, pos.pos_title as positionTitle, iu.nick_name as interviewerName from t_sch_appointment a left join t_tal t on t.tal_id = a.apt_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_pos pos on pos.pos_id = a.apt_position_id left join sys_user iu on iu.user_id = a.apt_interviewer_id where 1 = 1
and a.apt_status = #{status}
and a.apt_start_time >= #{from}
and a.apt_start_time <= #{to}
order by a.apt_start_time

select slt_id as slotId, slt_interviewer_id as interviewerId,
       date_format(slt_start_time, '%Y-%m-%d %H:%i') as startTime,
       date_format(slt_end_time, '%Y-%m-%d %H:%i') as endTime,
       slt_status as status,
       case when slt_status = 1 then '可用' else '已占用' end as statusLabel
from t_sch_slot
where slt_interviewer_id = #{interviewerId}

    and slt_start_time >= #{from}


    and slt_start_time <= #{to}

order by slt_start_time

select slt_id as slotId
from t_sch_slot
where slt_interviewer_id = #{interviewerId}
  and slt_status = 0
  and slt_start_time < #{endTime}
  and slt_end_time > #{startTime}

select slt_id
from t_sch_slot
where slt_interviewer_id = #{interviewerId}
  and slt_status = 1
  and slt_start_time = #{startTime}
  and slt_end_time = #{endTime}
limit 1

mapper.update:
update t_sch_slot
set slt_status = #{status}, slt_updated_at = now()
where slt_id = #{slotId}
